import pandas as pd
import numpy as np

for i in [1,3,4,7,8]:
    path = eval(f"experiment_{i}_csv")
    df = pd.read_csv(path)
    print(f"=== exp {i} ===", list(df.columns))
    print(df.describe().round(3).to_string())
    if 'FeedWaterFlowRate' in df.columns:
        for c in df.columns:
            if c not in ['unit_id','FeedWaterFlowRate'] and df[c].nunique()>1:
                r = df[['FeedWaterFlowRate',c]].corr().iloc[0,1]
                print(f"  corr flow~{c}: {r:.3f}")
    print()

